<template><view class="page"><text class="title">{{career.careerName}}</text><text class="intro">{{career.oneLineIntro}}</text><text class="section">主要做什么</text><text>{{career.mainWork}}</text><text class="section">一天可能做什么</text><text>{{career.dayExample}}</text><view class="actions"><button @click="add">加入探索清单</button><button type="primary" @click="finish">完成探索</button></view></view></template>
<script>import{getRecord,browseCareer,addExplorationItem,finishRecord,userMessage}from'@/api/zycck';export default{data:()=>({recordId:'',instanceId:'',gameId:'',careerId:'',career:{},readOnly:false}),onLoad(o){Object.assign(this,{recordId:o.recordId||'',instanceId:o.instanceId||'',gameId:o.gameId||'',careerId:o.careerId||'',readOnly:o.readOnly==='1'});this.load()},methods:{async load(){try{const r=await getRecord(this.recordId);const d=r.data||{};this.career=d.career||d.currentCareer||{careerId:this.careerId,careerName:'职业详情'};if(!this.readOnly)await browseCareer(this.recordId,this.careerId)}catch(e){uni.showToast({title:userMessage(e,'职业详情加载失败，请重试'),icon:'none'})}},async add(){if(this.readOnly)return;try{await addExplorationItem(this.recordId,this.careerId);uni.showToast({title:'已加入探索清单',icon:'success'})}catch(e){uni.showToast({title:userMessage(e,'加入清单失败，请重试'),icon:'none'})}},async finish(){if(this.readOnly)return;try{await finishRecord(this.recordId);uni.redirectTo({url:`/pages/zycck/exploration-list?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&readOnly=1`})}catch(e){uni.showToast({title:userMessage(e,'请先查看职业后再完成探索'),icon:'none'})}}}}</script>
<style scoped>.page{padding:40rpx}.title{display:block;font-size:46rpx;font-weight:700}.intro{display:block;margin:20rpx 0 40rpx;color:#64748b}.section{display:block;font-weight:700;margin-top:30rpx;margin-bottom:12rpx}.actions{display:flex;gap:20rpx;margin-top:70rpx}.actions button{flex:1}</style>
